@startuml

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class User {
  + ID : int
  + Name : string
  + Address : string
}

class RegularUser extends User {}

class BusinessUser extends User {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + TrackNumber : int
}

Album "1" *-- "1..*" Hit : contains

Artist "1" -- "1..*" Song : belongs to
BusinessUser "1" -- "*" Single : uploads
BusinessUser "1" -- "*" Hit : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : buys
RegularUser "1" -- "*" Album : suggests to

@enduml

